INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_ISL_EARLY_MODERN','Early-Modern Sufism (Ottoman/Safavid/Mughal)',1517,1850)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_SIRHINDI_MAKTUBAT','primary text','Ahmad Sirhindi, Maktubat (Collected Letters, early 17th c.)','Islamic/Sufi'),
 ('SRC_SHAH_WALIULLAH_HUJJAT','primary text','Shah Waliullah, Hujjat Allah al-Baligha (18th c.)','Islamic/Sufi'),
 ('SRC_NABULSI_DIWAN_HAQAIQ','primary text','Abd al-Ghani al-Nabulsi, devotional and Akbari commentarial corpus (e.g. al-Wujud al-Haqq; Diwan al-Haqa''iq, late 17th–early 18th c.)','Islamic/Sufi'),
 ('SRC_SHARANI_TABAQAT','primary text','Abd al-Wahhab al-Sha''rani, al-Tabaqat al-Kubra (Lawaqih al-Anwar; hagiographic lives of the saints, 16th c.)','Islamic/Sufi'),
 ('SRC_TIJANI_JAWAHIR','primary text','Ali Harazim, Jawahir al-Ma''ani (the foundational compendium of Ahmad al-Tijani''s teaching, early 19th c.)','Islamic/Sufi'),
 ('SRC_DARQAWI_RASAIL','primary text','Mawlay al-Arabi al-Darqawi, al-Rasa''il (Letters of guidance, early 19th c.)','Islamic/Sufi'),
 ('SRC_DAN_FODIO_IHYA','primary text','Uthman dan Fodio, Ihya al-Sunna wa-Ikhmad al-Bid''a and reform corpus (early 19th c.)','Islamic/Sufi'),
 ('SRC_BULLEH_SHAH_KAFIS','primary text','Bulleh Shah, Kafis (Punjabi Sufi poetry, 18th c.)','Islamic/Sufi'),
 ('SRC_BHITTAI_SHAH_JO_RISALO','primary text','Shah Abdul Latif Bhittai, Shah Jo Risalo (Sindhi Sufi poetry, 18th c.)','Islamic/Sufi'),
 ('SRC_BURSEVI_RUH_AL_BAYAN','primary text','Ismail Haqqi Bursevi, Ruh al-Bayan (Sufi Qur''an commentary, early 18th c.)','Islamic/Sufi')
INSERT INTO _e VALUES
 ('ENT_SUF_NAQSHBANDI_MUJADDIDI','Naqshbandi-Mujaddidi','Collective','Sufi order','Islamic/Sufi','Sufism / Sufi tariqa','A','Early-modern revivalist sub-branch of the Naqshbandiyya, named for Ahmad Sirhindi (the Mujaddid-i Alf-i Thani, ''Renewer of the Second Millennium''). Emphasized sober conformity to the Shari''a, silent dhikr, and rabita (bond to the shaykh); became the dominant Naqshbandi current across Mughal India, Central Asia, Ottoman lands, and beyond. Sub-branch of the existing ENT_SUF_NAQSHBANDI.'),
 ('ENT_SUF_TIJANIYYA','Tijaniyya','Collective','Sufi order','Islamic/Sufi','Sufism / Sufi tariqa','A','Tariqa founded by Ahmad al-Tijani (d.1815) in North Africa, claiming a direct waking-vision investiture from the Prophet Muhammad (the order''s distinctive ''seal of the saints'' claim). One of the largest Sufi orders of West and North Africa, with its own litanies (the Wazifa and Salat al-Fatih).'),
 ('ENT_SUF_KHALWATIYYA','Khalwatiyya','Collective','Sufi order','Islamic/Sufi','Sufism / Sufi tariqa','A','Order named for the practice of khalwa (spiritual retreat); spread widely across the Ottoman empire and Egypt in the early-modern period, producing many revival sub-branches. A principal vehicle of Ottoman-era Sufi piety and the seven-fold dhikr of the divine names.'),
 ('ENT_SUF_DARQAWIYYA','Darqawiyya','Collective','Sufi order','Islamic/Sufi','Sufism / Sufi tariqa','A','Moroccan revivalist branch of the Shadhili-Jazuli tradition founded by Mawlay al-Arabi al-Darqawi (d.1823), marked by ascetic poverty, ecstatic dhikr, and a renewal of the master-disciple bond; influential across North Africa and into the later Shadhili-Alawi line.'),
 ('ENT_SUF_SIRHINDI','Ahmad Sirhindi','Saint','Sufi reformer','Islamic/Sufi','Sufism / Naqshbandi reform','A','Indian Naqshbandi master (d.1624), titled Mujaddid-i Alf-i Thani (''Renewer of the Second Millennium''); founder-figure of the Naqshbandi-Mujaddidi branch. His Maktubat (Collected Letters) reformulated Sufi metaphysics, advancing wahdat al-shuhud (unity of witnessing) against an unqualified reading of Ibn Arabi''s wahdat al-wujud, and pressed for strict Shari''a conformity. Venerated human saint; not deified.'),
 ('ENT_SUF_NABULSI','Abd al-Ghani al-Nabulsi','Saint','Akbari commentator','Islamic/Sufi','Sufism / Akbari metaphysics','A','Damascene polymath, saint, and the foremost early-modern commentator on Ibn Arabi (the ''Akbari'' school) (d.1731). Defended wahdat al-wujud, wrote on dream interpretation, sacred travel, and Hanafi law; affiliated with both the Qadiri and Naqshbandi lineages. Venerated human saint.'),
 ('ENT_SUF_SHAH_WALIULLAH','Shah Waliullah of Delhi','Saint','Sufi reformer','Islamic/Sufi','Sufism / Islamic reform','A','Delhi-based scholar, Naqshbandi-affiliated Sufi, and seminal reformer (d.1762). His Hujjat Allah al-Baligha sought to reconcile law, hadith, and Sufi metaphysics and to harmonize wahdat al-wujud with wahdat al-shuhud; a foundational influence on later South Asian Islamic thought. Venerated human; not deified.'),
 ('ENT_SUF_TIJANI','Ahmad al-Tijani','Saint','Tariqa founder','Islamic/Sufi','Sufism / Sufi tariqa','A','Algerian-born founder of the Tijaniyya order (d.1815), one of the most widespread tariqas of West and North Africa. Claimed a direct waking-vision authorization from the Prophet and the rank of ''seal of the Muhammadan sainthood''. Venerated human saint.'),
 ('ENT_SUF_SHARANI','Abd al-Wahhab al-Sha''rani','Saint','Sufi reformer','Islamic/Sufi','Sufism / hagiography & law','A','Egyptian Shadhili saint, jurist, and hagiographer (d.1565). His Tabaqat al-Kubra is a major early-modern compendium of saints'' lives; he defended Sufism against legalist critics and harmonized the four Sunni schools. Founded an Egyptian Shadhili sub-line (Sha''rawiyya). Venerated human saint.'),
 ('ENT_SUF_BURSEVI','Ismail Haqqi Bursevi','Saint','Akbari commentator','Islamic/Sufi','Sufism / Jelveti order & exegesis','A','Ottoman Jelveti (Celveti) shaykh, Qur''an commentator, and Akbari-influenced mystic of Bursa (d.1725). His Ruh al-Bayan is a vast Sufi tafsir drawing heavily on Ibn Arabi and Rumi. Venerated human saint.'),
 ('ENT_SUF_NIYAZI_MISRI','Niyazi Misri','Saint','Saint-poet','Islamic/Sufi','Sufism / Khalwati order & poetry','A','Ottoman Khalwati shaykh and celebrated Turkish Sufi poet (d.1694); founder of the Misriyya branch of the Khalwatiyya. Known for ecstatic divan poetry and a turbulent career of exiles for his outspoken mysticism. Venerated human saint.'),
 ('ENT_SUF_DARQAWI','Mawlay al-Arabi al-Darqawi','Saint','Tariqa founder','Islamic/Sufi','Sufism / Sufi tariqa','A','Moroccan founder of the Darqawiyya, a revivalist branch of the Shadhili-Jazuli tradition (d.1823). His Letters (Rasa''il) are a classic of Sufi spiritual direction emphasizing poverty, sincerity, and ecstatic remembrance. Venerated human saint.'),
 ('ENT_SUF_DAN_FODIO','Uthman dan Fodio','Saint','Sufi reformer','Islamic/Sufi','Sufism / Qadiri reform (West Africa)','A','Fulani Qadiri scholar, reformer, poet, and founder of the Sokoto Caliphate in present-day Nigeria (d.1817). His jihad of reform and prolific Qadiri-Sufi writings (incl. Ihya al-Sunna) reshaped West African Islam. Venerated human; reformer-saint, not deified.'),
 ('ENT_SUF_MIR_DARD','Khwaja Mir Dard','Saint','Saint-poet','Islamic/Sufi','Sufism / Naqshbandi & Urdu poetry','A','Delhi Naqshbandi-Mujaddidi shaykh and major early Urdu poet (d.1785); developed the ''Muhammadan path'' (Tariqa Muhammadiyya Khalisa) within his father''s reform line. Venerated human saint and mystic-poet.'),
 ('ENT_SUF_BULLEH_SHAH','Bulleh Shah','Saint','Saint-poet','Islamic/Sufi','Sufism / Qadiri-Shattari & Punjabi poetry','A','Punjabi Sufi saint-poet (d.1757), disciple of the Qadiri-Shattari shaykh Inayat Shah Qadiri; his Kafis are among the most beloved works of Punjabi mystical poetry, voicing ecstatic divine love and social critique. Venerated human saint.'),
 ('ENT_SUF_BHITTAI','Shah Abdul Latif Bhittai','Saint','Saint-poet','Islamic/Sufi','Sufism / Sindhi poetry','A','Sindhi Sufi saint and poet (d.1752); his Shah Jo Risalo is the foundational classic of Sindhi mystical poetry, weaving local folk romances into allegories of the soul''s longing for God. Venerated human saint with a major shrine at Bhit Shah.'),
 ('ENT_SUF_SULTAN_BAHU','Sultan Bahu','Saint','Saint-poet','Islamic/Sufi','Sufism / Qadiri order & Punjabi poetry','A','Punjabi Qadiri Sufi saint and poet (d.1691); founder of the Sarwari Qadiri sub-line. Famed for his Punjabi ''Abyat'' couplets (each line ending ''Hu'') and Persian treatises on the path. Venerated human saint.'),
 ('ENT_SUF_JAZAIRI','Abd al-Qadir al-Jaza''iri','Saint','Akbari commentator','Islamic/Sufi','Sufism / Qadiri-Akbari & resistance','A','Algerian Qadiri amir, scholar, and Akbari Sufi (d.1883; formed in the early-modern Qadiri milieu, leader of the Algerian resistance 1832–1847). In Damascus he edited and championed Ibn Arabi''s al-Futuhat al-Makkiyya and wrote the mystical Kitab al-Mawaqif. Venerated human saint and Akbari authority.'),
 ('ENT_SUF_NAQSHBANDI_KHALID','Khalid al-Baghdadi','Saint','Sufi reformer','Islamic/Sufi','Sufism / Naqshbandi-Khalidi reform','A','Kurdish Naqshbandi-Mujaddidi master (d.1827), founder of the Khalidi sub-branch that revitalized the Naqshbandi order across the late-Ottoman world (Anatolia, the Levant, Kurdistan); stressed rabita, silent dhikr, and Shari''a-centered renewal. Venerated human saint.'),
 ('ENT_SUF_KARIM_KHALWATI','Mustafa al-Bakri','Saint','Sufi reformer','Islamic/Sufi','Sufism / Khalwati revival','B','Damascene-Egyptian Khalwati shaykh (d.1749), the great early-modern reviver of the Khalwatiyya whose disciples spread Khalwati sub-orders across Egypt and the Hijaz; a prolific author of litanies and travel works. Venerated human saint.'),
 ('ENT_SUF_NASAFI_DARA','Dara Shikoh','Saint','Akbari commentator','Islamic/Sufi','Sufism / Qadiri & comparative mysticism','B','Mughal prince and Qadiri Sufi (d.1659), disciple of Mulla Shah Badakhshi; pursued the unity of Sufi and Vedantic mysticism, translating the Upanishads (Sirr-i Akbar) and writing Majma al-Bahrayn (''The Mingling of the Two Oceans''). A figure of veneration in the Qadiri-syncretic stream; not deified.'),
 ('ENT_SUF_GAZARGAHI_HARAZIM','Ali Harazim al-Barada','Saint','Sufi reformer','Islamic/Sufi','Sufism / Tijani transmission','B','Foremost early disciple of Ahmad al-Tijani and compiler of the Jawahir al-Ma''ani, the foundational doctrinal compendium of the Tijaniyya (fl. early 19th c.). Venerated within the order as the principal transmitter of its master''s teaching.');
