 ('ENT_SUF_GAZARGAHI_HARAZIM','PER_ISL_EARLY_MODERN','Foremost early disciple of Ahmad al-Tijani and compiler of the Jawahir al-Ma''ani, the foundational doctrinal compendium of the Tijaniyya (fl. early 19th c.). Venerated within the order as the principal transmitter of its master''s teaching.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_SUF_NAQSHBANDI_MUJADDIDI','reception_of','ENT_SUF_NAQSHBANDI','high','The Mujaddidi is the early-modern revivalist sub-branch of the Naqshbandiyya, receiving and renewing its silsila and silent-dhikr method.'),
 ('ENT_SUF_NAQSHBANDI_MUJADDIDI','aligned_with','ENT_SUF_NAQSHBANDI','high','Doctrinally and organizationally continuous with the parent Naqshbandi order.'),
 ('ENT_SUF_SIRHINDI','member_of','ENT_SUF_NAQSHBANDI_MUJADDIDI','high','Sirhindi is the eponymous founder-figure (Mujaddid) of the Naqshbandi-Mujaddidi branch.'),
 ('ENT_SUF_SIRHINDI','member_of','ENT_SUF_NAQSHBANDI','high','Initiated into the Naqshbandi order (via Baqi Billah) before reforming it into the Mujaddidi line.'),
 ('ENT_SUF_SIRHINDI','reception_of','ENT_SUF_IBN_ARABI','high','Sirhindi''s wahdat al-shuhud was developed in critical reception of Ibn Arabi''s wahdat al-wujud, engaging the Akbari metaphysics directly.'),
 ('ENT_SUF_NABULSI','reception_of','ENT_SUF_IBN_ARABI','high','Al-Nabulsi was the foremost early-modern Akbari commentator, defending and expounding Ibn Arabi''s wahdat al-wujud.'),
 ('ENT_SUF_NABULSI','member_of','ENT_SUF_NAQSHBANDI','medium','Al-Nabulsi held Naqshbandi (and Qadiri) affiliation alongside his Akbari commitments.'),
 ('ENT_SUF_SHAH_WALIULLAH','member_of','ENT_SUF_NAQSHBANDI_MUJADDIDI','medium','Shah Waliullah was initiated in the Naqshbandi-Mujaddidi line and worked to harmonize its shuhudi reform with Akbari wujudi metaphysics.'),
 ('ENT_SUF_SHAH_WALIULLAH','reception_of','ENT_SUF_IBN_ARABI','high','His Hujjat Allah al-Baligha and related works engaged Ibn Arabi''s metaphysics, seeking to reconcile wahdat al-wujud with Sirhindi''s wahdat al-shuhud.'),
 ('ENT_SUF_TIJANIYYA','aligned_with','ENT_SUF_TARIQA','high','The Tijaniyya is a tariqa (Sufi path), instantiating the general category of the Sufi order.'),
 ('ENT_SUF_TIJANI','member_of','ENT_SUF_TIJANIYYA','high','Ahmad al-Tijani is the eponymous founder and supreme master of the Tijaniyya.'),
 ('ENT_SUF_GAZARGAHI_HARAZIM','member_of','ENT_SUF_TIJANIYYA','high','Ali Harazim was Tijani''s foremost disciple and compiler of the order''s foundational text.'),
 ('ENT_SUF_GAZARGAHI_HARAZIM','taught_by','ENT_SUF_TIJANI','high','Harazim received the teaching directly from Ahmad al-Tijani, recording it in the Jawahir al-Ma''ani.'),
 ('ENT_SUF_DARQAWIYYA','aligned_with','ENT_SUF_TARIQA','high','The Darqawiyya is a Shadhili-derived tariqa, instantiating the Sufi-order category.'),
 ('ENT_SUF_DARQAWI','member_of','ENT_SUF_DARQAWIYYA','high','Mawlay al-Arabi al-Darqawi is the eponymous founder of the Darqawiyya.'),
 ('ENT_SUF_KHALWATIYYA','aligned_with','ENT_SUF_TARIQA','high','The Khalwatiyya is a major tariqa, instantiating the Sufi-order category.'),
 ('ENT_SUF_NIYAZI_MISRI','member_of','ENT_SUF_KHALWATIYYA','high','Niyazi Misri founded the Misriyya branch of the Khalwatiyya.'),
 ('ENT_SUF_KARIM_KHALWATI','member_of','ENT_SUF_KHALWATIYYA','high','Mustafa al-Bakri was the great early-modern reviver and master of the Khalwatiyya.'),
 ('ENT_SUF_BURSEVI','reception_of','ENT_SUF_IBN_ARABI','high','Bursevi''s tafsir Ruh al-Bayan draws heavily on Akbari metaphysics, transmitting Ibn Arabi''s teaching.'),
